select plan(23);
insert into auth.users(id,email) values('00000000-0000-4000-8000-000000000501','budget-accounting@example.test'),('00000000-0000-4000-8000-000000000502','budget-staff@example.test'),('00000000-0000-4000-8000-000000000503','budget-brand@example.test');
update public.profiles set role='accounting' where id='00000000-0000-4000-8000-000000000501';
update public.profiles set role='staff' where id='00000000-0000-4000-8000-000000000502';
insert into public.brands(id,name) values('00000000-0000-4000-8000-000000000504','Budget A'),('00000000-0000-4000-8000-000000000505','Budget B');
insert into public.brand_users(brand_id,user_id) values('00000000-0000-4000-8000-000000000504','00000000-0000-4000-8000-000000000503');
insert into public.seasons(id,brand_id,code,name) values('00000000-0000-4000-8000-000000000508','00000000-0000-4000-8000-000000000504','A','A'),('00000000-0000-4000-8000-000000000510','00000000-0000-4000-8000-000000000505','B','B');
insert into public.customers(id,legal_name) values('00000000-0000-4000-8000-000000000509','Budget Customer');
insert into public.budgets(id,brand_id,amount_cents,period_start,period_end) values('00000000-0000-4000-8000-000000000506','00000000-0000-4000-8000-000000000504',12345,'2026-01-01','2026-01-31');
insert into public.budget_private(id,brand_id,notes) values('00000000-0000-4000-8000-000000000506','00000000-0000-4000-8000-000000000504','Secret budget notes');
select throws_ok($$insert into public.budgets(brand_id,amount_cents,period_start,period_end) values('00000000-0000-4000-8000-000000000504',100,'2026-01-31','2026-02-10')$$,'23P01',null,'inclusive overlap rejected including null scopes');
select lives_ok($$insert into public.budgets(brand_id,amount_cents,period_start,period_end) values('00000000-0000-4000-8000-000000000504',100,'2026-02-01','2026-02-28')$$,'adjacent nonoverlap accepted');
select lives_ok($$insert into public.budgets(brand_id,season_id,amount_cents,period_start,period_end) values('00000000-0000-4000-8000-000000000504','00000000-0000-4000-8000-000000000508',100,'2026-01-01','2026-01-31')$$,'specific season separate from null scope');
select lives_ok($$insert into public.budgets(brand_id,customer_id,amount_cents,period_start,period_end) values('00000000-0000-4000-8000-000000000504','00000000-0000-4000-8000-000000000509',100,'2026-01-01','2026-01-31')$$,'specific customer separate from null scope');
select lives_ok($$insert into public.budgets(brand_id,amount_cents,period_start,period_end) values('00000000-0000-4000-8000-000000000505',100,'2026-01-01','2026-01-31')$$,'different brand independent');
select throws_ok($$insert into public.budgets(brand_id,season_id,amount_cents,period_start,period_end) values('00000000-0000-4000-8000-000000000504','00000000-0000-4000-8000-000000000510',100,'2026-01-01','2026-01-31')$$,'23514',null,'cross-brand season rejected');
select throws_ok($$insert into public.budgets(brand_id,amount_cents,period_start,period_end) values('00000000-0000-4000-8000-000000000504',-1,'2026-03-01','2026-03-31')$$,'23514',null,'negative money rejected');
select throws_ok($$update public.budgets set brand_id='00000000-0000-4000-8000-000000000505' where id='00000000-0000-4000-8000-000000000506'$$,'23514',null,'identity cannot change');
set local role authenticated;set local request.jwt.claim.sub='00000000-0000-4000-8000-000000000501';
select lives_ok($$select public.save_budget('00000000-0000-4000-8000-000000000506','{"brand_id":"00000000-0000-4000-8000-000000000504","season_id":"","customer_id":"","amount_cents":23456,"period_start":"2026-01-01","period_end":"2026-01-31","notes":"Updated notes"}',(select updated_at from public.budgets where id='00000000-0000-4000-8000-000000000506'))$$,'accounting updates budget and notes atomically');
select is((select notes from public.budget_private where id='00000000-0000-4000-8000-000000000506'),'Updated notes','notes persisted');
select throws_ok($$select public.save_budget('00000000-0000-4000-8000-000000000506',jsonb_build_object('brand_id','00000000-0000-4000-8000-000000000504','season_id','','customer_id','','amount_cents',99999,'period_start','2026-01-01','period_end','2026-01-31','notes',repeat('x',5001)),(select updated_at from public.budgets where id='00000000-0000-4000-8000-000000000506'))$$,'23514',null,'invalid private notes roll back entire save');
select is((select amount_cents from public.budgets where id='00000000-0000-4000-8000-000000000506'),23456::bigint,'failed transaction keeps previous amount');
select throws_ok($$select public.save_budget('00000000-0000-4000-8000-000000000506','{"brand_id":"00000000-0000-4000-8000-000000000504"}','2020-01-01')$$,'P0002',null,'stale update rejected');
set local request.jwt.claim.sub='00000000-0000-4000-8000-000000000502';
select is((select count(*) from public.budgets where brand_id in('00000000-0000-4000-8000-000000000504','00000000-0000-4000-8000-000000000505')),5::bigint,'staff reads budgets');
with x as(update public.budgets set amount_cents=1 where id='00000000-0000-4000-8000-000000000506' returning id) select is((select count(*) from x),0::bigint,'staff cannot update');
select throws_ok($$select public.save_budget(null,'{}')$$,'42501',null,'staff RPC forbidden');
set local request.jwt.claim.sub='00000000-0000-4000-8000-000000000503';
select is((select count(*) from public.budgets where brand_id='00000000-0000-4000-8000-000000000504'),4::bigint,'brand reads own budgets');
select is((select count(*) from public.budgets where brand_id='00000000-0000-4000-8000-000000000505'),0::bigint,'brand cannot read others');
select is((select count(*) from public.budget_private),0::bigint,'brand cannot read internal notes');
select throws_ok($$insert into public.budgets(brand_id,amount_cents,period_start,period_end) values('00000000-0000-4000-8000-000000000504',100,'2026-03-01','2026-03-31')$$,'42501',null,'brand cannot write business budgets');
set local request.jwt.claim.sub='00000000-0000-4000-8000-000000000501';
select lives_ok($$update public.budgets set deleted_at=now() where id='00000000-0000-4000-8000-000000000506'$$,'accounting archives');
set local request.jwt.claim.sub='00000000-0000-4000-8000-000000000503';
select is((select count(*) from public.budgets where id='00000000-0000-4000-8000-000000000506'),0::bigint,'archived budget hidden from brand');
reset role;
select ok(exists(select 1 from public.audit_log where table_name='budgets' and record_id='00000000-0000-4000-8000-000000000506' and action='update'),'budget update audited');
